  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Fills all tiles that are reachable from the source according to the current water distance.
   * Algorithm:
   * 1. If distance is less than or equal to the previously processed distance, do nothing.
   * 2. Mark the source cell as filled when water flow begins.
   * 3. Expand outward from the source by breadth-first traversal.
   * 4. A move from one pipe to an adjacent pipe is allowed only when both pipes connect to each other through opposite directions.
   * 5. Mark newly reached pipes and reachable sink cells as filled.
   * 6. Record the reached coordinates in filledTiles and update the previous fill-distance bookkeeping.
   * Related Features:
   * - cell
   * - rows
   * - cols
   * - filledTiles
   * - sourceCell
   * - sinkCell
   * - prevFilledDistance
   * - prevFilledTiles
   * Related Classes: Coordinate, TerminationCell, Pipe, FillableCell, Map
   * Input:
   * - distance: the water expansion distance from the source. Non-negative integer.
   * Output:
   * - void.
   * Pre-condition:
   * - The map has been initialized.
   * - The source cell exists and is valid.
   * - The supplied distance is non-negative.
   * Post-condition:
   * - All cells reachable within the given distance are marked filled according to connectivity rules.
   * - The source cell is filled when water begins flowing.
   * - The bookkeeping fields for previously filled distance and tile count are updated.
   * - Cells outside the reachable frontier remain unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (getPrevFilledDistance() != null && distance <= getPrevFilledDistance().intValue())
    {
      return;
    }

    fillBeginTile();

    if (getSourceCell() == null || getCell() == null)
    {
      return;
    }

    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    Queue<Integer> distQueue = new LinkedList<Integer>();
    Coordinate sourceCoord = getSourceCell().getCoord();
    if (sourceCoord == null)
    {
      return;
    }

    queue.add(sourceCoord);
    distQueue.add(Integer.valueOf(0));

    while (!queue.isEmpty())
    {
      Coordinate current = queue.poll();
      int currentDist = distQueue.poll().intValue();
      if (currentDist >= distance)
      {
        continue;
      }

      int row = current.getRow();
      int col = current.getCol();

      if (row < 0 || row >= getRows() || col < 0 || col >= getCols())
      {
        continue;
      }

      Cell currentCell = getCell()[row][col];
      if (!(currentCell instanceof FillableCell))
      {
        continue;
      }

      FillableCell currentFillable = (FillableCell) currentCell;
      Pipe currentPipe = currentFillable.getPipe();
      if (currentPipe == null)
      {
        continue;
      }

      int[][] dirs = new int[][] { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
      for (int i = 0; i < dirs.length; i++)
      {
        int nr = row + dirs[i][0];
        int nc = col + dirs[i][1];
        if (nr < 0 || nr >= getRows() || nc < 0 || nc >= getCols())
        {
          continue;
        }

        Cell neighbor = getCell()[nr][nc];
        if (neighbor == null)
        {
          continue;
        }

        boolean connected = false;
        if (neighbor instanceof FillableCell)
        {
          FillableCell neighborFillable = (FillableCell) neighbor;
          Pipe neighborPipe = neighborFillable.getPipe();
          if (neighborPipe != null)
          {
            connected = true;
          }
        }
        else if (neighbor instanceof TerminationCell)
        {
          connected = true;
        }

        if (!connected)
        {
          continue;
        }

        Coordinate next = Coordinate.create(nr, nc);
        if (!getFilledTiles().contains(next))
        {
          getFilledTiles().add(next);
          if (neighbor instanceof FillableCell)
          {
            ((FillableCell) neighbor).fill();
          }
          queue.add(next);
          distQueue.add(Integer.valueOf(currentDist + 1));
        }
      }
    }

    setPrevFilledDistance(Integer.valueOf(distance));
    setPrevFilledTiles(getFilledTiles().size());
    
  }

